import{_ as e,o as t,c as a,a3 as r}from"./chunks/framework.DdpBa4_E.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/10-关于世代用语的界定.md","filePath":"books/xialiu-shehui/10-关于世代用语的界定.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/10-关于世代用语的界定.md"};function _(s,p,i,n,u,l){return t(),a("div",null,[...p[0]||(p[0]=[r('<h2 id="关于世代用语的界定" tabindex="-1">关于世代用语的界定 <a class="header-anchor" href="#关于世代用语的界定" aria-label="Permalink to &quot;关于世代用语的界定&quot;">​</a></h2><p>本书主要是从世代的角度来分析社会阶层的问题，故将有关世代的用语在此先作一界定。</p><p>“团块世代”</p><p>一般作为第一次育婴潮世代的同义语而使用，狭义上指自1947年至1949年每年新生儿高达270万的这三年中所出生的约861万人，广义上有时也指自1945年至1952年前后出生的人群，即日本在二战后的最初几年当中出生的人群。假设从1947年算到1951年，出生人数共1253万人，现在仍有1087万人在世。但在本书后面将要叙述到的调查中，只以1946年至1950年出生的人群为调查对象（参照三浦展著《团块世代综述》）。</p><p>“团块次代”</p><p>一般作为第二次育婴潮世代的同义语而使用，即指1971年至1974年间所出生的人群，当时每年约有200万新生儿出生，4年间共出生约800万人。这一代人很容易因望文生义而被误认为是团块世代的下一代，但笔者根据厚生劳动省发表的“人口动态统计”，证明第二次育婴潮世代的父母亲多数并非团块世代，故而给这一世代起了一个名字：“伪团块次代”，但在本书中仍沿袭社会的一般称呼，将自1970年至1974年前后出生的人群称为“团块次代”。不过，在后面将要叙述到的调查中，则是以1971年至1975年出生的人群为调查对象（参照三浦展著《1400万人的团块次代将成为市场中核》）。</p><p>“真性团块次代”</p><p>笔者依据厚生劳动省发表的“人口动态统计”，析出了团块世代所生育子女比例最高的世代，即1973年至1980年出生的人群，这些人群中有超过50%以上的人为团块世代的下一代，因此姑且将这一世代称为“真性团块次代”。笔者还注意到，团块世代的男性所生育的下一代尤其集中在1975年至1979年间，因此这一人群可谓是最名实相符的“真性团块次代”（参照三浦展著《无房一代》）。</p><p>“新人类世代”</p><p>“新人类世代”是一个在人口学意义上无法定义的世代，即使是在一般意义上，也不存在一个内涵清晰的界定。最早提出这个名称的应该是笔者曾经供职过的PARCO公司所属的市场营销杂志《ACROSS》，在它的1984年第6期中，将1968年前后出生的人群称为“新人类”，从此得名。现在，从社会经济发展的视角出发，笔者将新人类世代定义为：日本经济高速发展时期出生的人群。一般社会学家将1955年至1973年这段时期称为日本经济高速发展时期，但笔者建议将其间“国民收入倍增计划”发表至达成的1960年至1968年间出生的人群定义为新人类世代，换句话说，新人类世代是在日本经济发展最为迅猛时期出生的世代。后面所引用的调查则以1961年至1965年间出生的人群为调查对象（参照三浦展著《新人类，做父母！》）。</p><p>“昭和初年世代”</p><p>昭和初年世代指的是昭和元年至昭和九年（1926—1934年）出生的人群，1955年至1973年经济高速发展时期他们正值20—40岁，不仅见证了日本的经济腾飞，也是支撑日本经济飞速发展的中坚力量。新人类世代则是昭和初年世代（尤其是男性）的下一代。后面所引用的调查以1931年至1937年出生的人群为昭和初年世代的调查对象。</p><p>本书所援引的调查概要说明</p><p>昭和四世代欲求比较调查（以下简称“欲求调查”）</p><p>调查日：2004年11月12日（星期五）—30日（星期二）</p><p>调查方法：寄送问卷法（问卷回收与一部分面对面访问并用）</p><p>调查对象：东京都及周边三县居住者共计800名，下记世代各200名昭和初年世代　1931年—1937年出生人群团块世代　1946年—1950年出生人群新人类世代　1961年—1965年出生人群团块次代　1971年—1975年出生人群问卷发放方法：根据2003年1月（千叶县为4月）各都县发表的男女各年龄组的人口，从上述各都县中抽取样本问卷回收数：共寄送1150份，回收929份，其中有效问卷861份，从中从各世代组各随机抽取100名调查实施者：（株式会社）Survey Research Center统计分析：（株式会社）e-FALCON调查策划及组织实施、综合分析：Culture Studies研究所第一次女性阶层化调查调查日：2005年5月18日（星期三）—22日（星期日）</p><p>调查方法：网上在线调查</p><p>调查对象：东京都及周边三县女性居住者共计2000名</p><p>其中：18—22岁　500人</p><p>23—27岁　500人</p><p>28—32岁　500人</p><p>33—37岁　500人</p><p>调查对象选取方法：将东京都及周边三县划分为6个地区：东京都市中心23区、东京郊区、横滨及川崎市、神奈川县除横滨川崎以外的地区、埼玉县、千叶县，根据平成十二年（2000年）10月全国人口普查的结果，推算出6个地区上述各年龄段的居住者人数比例以及6个地区的未婚率和已婚率，按照其比例选取上述各年龄段的调查样本数。同时，参照Attractors Lab株式会社“日本未来人口推计”（2001年推计）的数据，假设23—27岁的未婚率为3%、28—32岁的未婚率为5%、33—37岁的未婚率为5%，各年龄段的未婚率都呈上升趋势，因而对各年龄的调查样本数进行了微调。</p><p>调查实施及统计分析：（株式会社）Think To</p><p>调查后援：（株式会社）读卖广告社</p><p>调查策划及组织实施、综合分析：Culture Studies研究所第二次女性阶层化调查调查日：2005年6月21日（星期二）—26日（星期日）</p><p>调查方法：网上调查</p><p>调查对象：东京都及周边三县女性居住者共计600名</p><p>其中：18—22岁　150人</p><p>23—27岁　150人</p><p>28—32岁　150人</p><p>33—37岁　150人</p><p>调查对象选取方法：同第一次调查</p><p>调查实施及统计分析：（株式会社）Think To</p><p>调查后援：（株式会社）读卖广告社</p><p>调查策划及组织实施、综合分析：Culture Studies研究所本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',37)])])}const d=e(o,[["render",_]]);export{c as __pageData,d as default};
